sys_ui_action.client_script_v2:
function onClick(g_form) {
    g_modal.confirm("Confirmação", "Deseja criar a marca?", function(confirmed) {
        if (confirmed) {
            // Exibe a mensagem de "Aguarde..."
            g_form.clearMessages(); // Limpa mensagens anteriores, se houver.
            g_form.addInfoMessage('Aguarde...');

            // Executa o submit e aguarda a finalização para prosseguir.
            g_form.submit('atualizarSAP')
                .then(function() {
                    // Quando o submit finalizar, limpa as mensagens e exibe "Concluído".
                    g_form.clearMessages();
                    g_form.addInfoMessage('Processo concluído com sucesso!');
                })
                .catch(function(error) {
                    // Em caso de erro, exibe uma mensagem apropriada.
                    g_form.clearMessages();
                    g_form.addErrorMessage('Ocorreu um erro durante o processo: ' + error.message);
                });
        }
    });
}

sys_ui_action.script:
function atualizarSAP() {
    gsftSubmit(null, g_form.getFormElement(), 'atualizarSAP');
}
if (typeof window == 'undefined') {
    integrateSAPmarca();
}


function integrateSAPmarca() {
    try {
        var aux = new x_asscs_integra.SAPintegraUtils().attBrand(current);
        //gs.addInfoMessage("PKLOG " + aux);

        var r;
        try {
            r = JSON.parse(aux);
        } catch (jsonError) {
            gs.addErrorMessage('Erro ao fazer parse do JSON: ' + aux);
            throw new Error('Erro no parsing do JSON: ' + aux);
        }

        // gs.addInfoMessage('r ' + JSON.stringify(r));

        var rstatus = r.http || 0;
        // gs.addInfoMessage('STATUS ' + rstatus);

        var msg = '';

        if ([200, 201, 202].includes(rstatus)) {

            var response = JSON.parse(r.responseBody || '{}');
            var brandCode = response.BrandCode || 'Não encontrado';

            var criacaoMarca = criarMarcarServiceNow(current, brandCode);

            msg += '\n\n Marca atualizada com sucesso \n\n ' + 'Código da Marca no SAP: ' + brandCode;
            current.work_notes = msg;
            current.marca_cadastrada_alterada = true;
			current.u_codigo_marca = brandCode;
            current.update();
            action.setRedirectURL(current);
        } else {
            current.work_notes = '\n\n Houve um erro na atualização de marca.\n\n' + JSON.stringify(r);
            current.update();
            action.setRedirectURL(current);
        }
    } catch (e) {
        var errorMsg = 'Catch Houve um erro na atualização de marca.\n\n' + (e.message || '');
        current.work_notes = errorMsg;
        current.update();
        action.setRedirectURL(current);
        gs.addErrorMessage('Houve um erro na atualização de marca. Consulte as notas para mais detalhes.');
    }
}

function criarMarcarServiceNow(current, brandCode) {
    var grMarca = new GlideRecord('x_asscs_allos_marca');
    grMarca.addEncodedQuery('codigo_da_marca=' + brandCode);
    grMarca.query();

    if (grMarca.next()) {
        grMarca.u_network_name = current.variables.nome_da_marca.getDisplayValue();
        grMarca.u_bahia_nature_project = current.variables.natureza_projeto_bahia.getValue();
        grMarca.u_macrosegment = current.variables.macrosegmento.getValue();
        grMarca.codigo_da_marca = brandCode;
        grMarca.update();
    }

}
